This is the only test that answers "would this paymaster pay for *me*". It's free, unlimited, and works
on unverified contracts. Every paymaster restricts `msg.sender` to the EntryPoint, so you **spoof `from`**
— which `eth_call` lets you do for free, because nothing is signed.

```js
const I = new ethers.Interface([
  // v0.7+ shape. For v0.6 swap in the 11-field tuple and selector 0xf465c77e.
  'function validatePaymasterUserOp(' +
  'tuple(address sender,uint256 nonce,bytes initCode,bytes callData,bytes32 accountGasLimits,' +
  'uint256 preVerificationGas,bytes32 gasFees,bytes paymasterAndData,bytes signature) userOp,' +
  'bytes32 userOpHash, uint256 maxCost) returns (bytes context, uint256 validationData)'
]);

const op = {
  sender: MY_SMART_ACCOUNT, nonce: 0n, initCode: '0x', callData: '0x',
  accountGasLimits: pack(100000, 100000),      // verificationGasLimit | callGasLimit
  preVerificationGas: 50000n,
  gasFees: pack(1000000, 10000000),            // maxPriorityFeePerGas | maxFeePerGas
  paymasterAndData: ethers.concat([PAYMASTER, pack(60000, 60000)]),   // >= 52 bytes, see §2
  signature: '0x',
};

await rpc('eth_call', [{
  from: ENTRYPOINT_THAT_PAYMASTER_SERVES,   // <-- the spoof. must be the RIGHT version.
  to:   PAYMASTER,
  data: I.encodeFunctionData('validatePaymasterUserOp', [op, ethers.ZeroHash, 10n**15n]),
  gas:  '0x2625a0',
